y=dP_dt
def run(k,fn):
    G=fn(k)
    terms={"G":G,"tG":t*G,"t":t,"P":P,"tP":t*P,"P2":P**2,"tP2":t*P**2,"P3":P**3,"tP3":t*P**3,"GP":G*P,"GP2":G*P**2,"GP3":G*P**3,"P2tG":P**2*t*G}
    X=np.array(list(terms.values())).T
